import React, { useState, useEffect } from 'react';
import { useNavigate, useParams, Link } from 'react-router-dom';
import { projectsAPI } from '../../services/api';
import AppLayout from '../../components/layout/AppLayout';
import toast from 'react-hot-toast';

const STATUS_CONFIG = {
  planifie:  { label: 'Planifié',  color: '#6366F1', bg: 'rgba(99,102,241,0.12)'  },
  en_cours:  { label: 'En cours',  color: '#F59E0B', bg: 'rgba(245,158,11,0.12)'  },
  suspendu:  { label: 'Suspendu',  color: '#EF4444', bg: 'rgba(239,68,68,0.12)'   },
  termine:   { label: 'Terminé',   color: '#10B981', bg: 'rgba(16,185,129,0.12)'  },
};

function StatusBadge({ status }) {
  const cfg = STATUS_CONFIG[status] || { label: status, color: '#9CA3AF', bg: 'rgba(156,163,175,0.12)' };
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 5, padding: '4px 12px', borderRadius: 100, fontSize: 13, fontWeight: 600, color: cfg.color, background: cfg.bg }}>
      <span style={{ width: 7, height: 7, borderRadius: '50%', background: cfg.color }} />
      {cfg.label}
    </span>
  );
}

function InfoRow({ label, value, highlight }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', padding: '10px 0', borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
      <span style={{ fontSize: 13, color: 'var(--gray-3)' }}>{label}</span>
      <span style={{ fontSize: highlight ? 15 : 13, fontWeight: 600, color: highlight || 'var(--white)', fontFamily: highlight ? 'var(--font-display)' : 'inherit' }}>
        {value || <span style={{ color: 'var(--gray-4)', fontStyle: 'italic', fontWeight: 400, fontSize: 12 }}>Non renseigné</span>}
      </span>
    </div>
  );
}

function BudgetStats({ stats, project }) {
  const budget = parseFloat(project.budget) || 0;
  const expenses = parseFloat(project.actual_expenses) || 0;
  const contractsTotal = stats?.contracts_total || 0;
  const consumed = budget > 0 ? Math.min(100, (expenses / budget) * 100) : 0;
  const contractCoverage = budget > 0 ? Math.min(100, (contractsTotal / budget) * 100) : 0;

  const fmt = (n) => {
    if (!n) return '0 DA';
    if (n >= 1_000_000) return (n / 1_000_000).toFixed(2) + ' M DA';
    if (n >= 1_000) return (n / 1_000).toFixed(0) + ' K DA';
    return n.toFixed(0) + ' DA';
  };

  return (
    <div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 16, marginBottom: 24 }}>
        {[
          { label: 'Budget prévisionnel', value: fmt(budget), icon: '💼', color: '#6366F1' },
          { label: 'Dépenses réelles', value: fmt(expenses), icon: '💸', color: consumed > 85 ? '#EF4444' : '#F59E0B' },
          { label: 'Montant des contrats', value: fmt(contractsTotal), icon: '📄', color: '#10B981' },
        ].map((s, i) => (
          <div key={i} className="card" style={{ padding: '20px 22px', borderTop: `2px solid ${s.color}` }}>
            <div style={{ fontSize: 22, marginBottom: 10 }}>{s.icon}</div>
            <div style={{ fontSize: 20, fontWeight: 800, fontFamily: 'var(--font-display)', color: s.color, marginBottom: 4 }}>{s.value}</div>
            <div style={{ fontSize: 12, color: 'var(--gray-3)', textTransform: 'uppercase', letterSpacing: '0.5px' }}>{s.label}</div>
          </div>
        ))}
      </div>

      <div className="card">
        <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 15, fontWeight: 700, marginBottom: 20, color: 'var(--gold)' }}>
          📊 Avancement budgétaire
        </h3>
        <div style={{ marginBottom: 20 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 13, marginBottom: 8 }}>
            <span style={{ color: 'var(--gray-3)' }}>Dépenses réelles vs Budget</span>
            <span style={{ fontWeight: 700, color: consumed > 85 ? '#EF4444' : 'var(--gold)' }}>{consumed.toFixed(1)}%</span>
          </div>
          <div style={{ height: 10, background: 'var(--dark-border)', borderRadius: 5, overflow: 'hidden' }}>
            <div style={{ height: '100%', width: `${consumed}%`, background: consumed > 85 ? 'linear-gradient(90deg, #EF4444, #F87171)' : 'linear-gradient(90deg, var(--gold-dark), var(--gold))', borderRadius: 5, transition: 'width 0.8s ease' }} />
          </div>
          {budget > 0 && (
            <div style={{ fontSize: 12, color: 'var(--gray-4)', marginTop: 6 }}>
              Reste : {fmt(budget - expenses)} • Écart contrats/budget : {fmt(contractsTotal - expenses)}
            </div>
          )}
        </div>
        <div>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 13, marginBottom: 8 }}>
            <span style={{ color: 'var(--gray-3)' }}>Couverture contractuelle vs Budget</span>
            <span style={{ fontWeight: 700, color: '#10B981' }}>{contractCoverage.toFixed(1)}%</span>
          </div>
          <div style={{ height: 10, background: 'var(--dark-border)', borderRadius: 5, overflow: 'hidden' }}>
            <div style={{ height: '100%', width: `${contractCoverage}%`, background: 'linear-gradient(90deg, #059669, #10B981)', borderRadius: 5, transition: 'width 0.8s ease' }} />
          </div>
        </div>
      </div>
    </div>
  );
}

function ContractsList({ contracts }) {
  if (!contracts?.length) return (
    <div className="card" style={{ textAlign: 'center', padding: '48px 24px' }}>
      <div style={{ fontSize: 48, marginBottom: 12 }}>📄</div>
      <p style={{ color: 'var(--gray-3)', fontSize: 14 }}>Aucun contrat associé à ce projet.</p>
    </div>
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      {contracts.map(c => {
        const montant = c.summary?.section2?.conditions_financieres?.montant_ttc || c.summary?.montant_total || null;
        return (
          <div key={c.id} className="card" style={{ padding: '16px 20px', display: 'flex', alignItems: 'center', gap: 16 }}>
            <span style={{ fontSize: 28 }}>{c.file_type === 'pdf' ? '📕' : '📘'}</span>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontWeight: 600, fontSize: 14, marginBottom: 3, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{c.file_name}</div>
              <div style={{ fontSize: 12, color: 'var(--gray-3)' }}>
                {c.file_type?.toUpperCase()} • {(c.file_size / 1024).toFixed(0)} KB • {new Date(c.created_at).toLocaleDateString('fr-FR')}
              </div>
            </div>
            {montant && (
              <div style={{ textAlign: 'right', flexShrink: 0 }}>
                <div style={{ fontSize: 11, color: 'var(--gray-4)', marginBottom: 2 }}>Montant TTC</div>
                <div style={{ fontSize: 14, fontWeight: 700, color: 'var(--gold)' }}>{montant}</div>
              </div>
            )}
            <div style={{ flexShrink: 0 }}>
              {c.is_processing ? (
                <span style={{ fontSize: 12, color: '#F59E0B' }}>⏳ En cours...</span>
              ) : (
                <span style={{ fontSize: 12, color: '#10B981' }}>✅ Analysé</span>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function DailyReportsList({ projectId }) {
  const navigate = useNavigate();
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      try {
        const res = await projectsAPI.listReports(projectId);
        setReports(res.data);
      } catch {
        toast.error('Impossible de charger les rapports');
      } finally {
        setLoading(false);
      }
    })();
  }, [projectId]);

  const WEATHER_ICONS = { ensoleille: '☀️', nuageux: '☁️', pluvieux: '🌧️', venteux: '💨', orageux: '⛈️' };

  if (loading) return <div style={{ color: 'var(--gray-3)', padding: 24 }}>Chargement...</div>;

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
        <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 18 }}>Journal de chantier ({reports.length} entrées)</h3>
        <button className="btn-primary" onClick={() => navigate(`/projects/${projectId}/reports/new`)}
          style={{ padding: '10px 18px', fontSize: 14 }}>
          + Nouveau rapport
        </button>
      </div>

      {reports.length === 0 ? (
        <div className="card" style={{ textAlign: 'center', padding: '48px 24px' }}>
          <div style={{ fontSize: 48, marginBottom: 12 }}>📓</div>
          <p style={{ color: 'var(--gray-3)', fontSize: 14, marginBottom: 20 }}>Aucun rapport journalier pour ce projet.</p>
          <button className="btn-primary" onClick={() => navigate(`/projects/${projectId}/reports/new`)}>
            Rédiger le premier rapport
          </button>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {reports.map(r => (
            <div key={r.id} className="card" style={{ padding: '16px 20px', cursor: 'pointer' }}
              onClick={() => navigate(`/projects/${projectId}/reports/${r.id}`)}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 }}>
                    <span style={{ fontSize: 18 }}>{WEATHER_ICONS[r.weather] || '📅'}</span>
                    <span style={{ fontWeight: 700, fontFamily: 'var(--font-display)', fontSize: 15 }}>
                      {new Date(r.report_date).toLocaleDateString('fr-FR', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' })}
                    </span>
                  </div>
                  <p style={{ fontSize: 13, color: 'var(--gray-3)', lineHeight: 1.5, overflow: 'hidden', display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical' }}>
                    {r.work_done}
                  </p>
                </div>
                <div style={{ display: 'flex', gap: 16, marginLeft: 24, flexShrink: 0 }}>
                  <div style={{ textAlign: 'center' }}>
                    <div style={{ fontSize: 20, fontWeight: 800, fontFamily: 'var(--font-display)', color: 'var(--gold)' }}>{r.workers_count}</div>
                    <div style={{ fontSize: 10, color: 'var(--gray-4)', textTransform: 'uppercase' }}>Ouvriers</div>
                  </div>
                  {r.progress_pct !== null && (
                    <div style={{ textAlign: 'center' }}>
                      <div style={{ fontSize: 20, fontWeight: 800, fontFamily: 'var(--font-display)', color: '#10B981' }}>{r.progress_pct}%</div>
                      <div style={{ fontSize: 10, color: 'var(--gray-4)', textTransform: 'uppercase' }}>Avancement</div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default function ProjectDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [project, setProject] = useState(null);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  const [editing, setEditing] = useState(false);
  const [editForm, setEditForm] = useState({});
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const [pRes, sRes] = await Promise.all([
          projectsAPI.get(id),
          projectsAPI.getBudgetStats(id),
        ]);
        setProject(pRes.data);
        setStats(sRes.data);
        setEditForm(pRes.data);
      } catch {
        toast.error('Projet introuvable');
        navigate('/projects');
      } finally {
        setLoading(false);
      }
    })();
  }, [id]);

  const handleSave = async () => {
    setSaving(true);
    try {
      const res = await projectsAPI.update(id, editForm);
      setProject(res.data);
      setEditForm(res.data);
      setEditing(false);
      toast.success('Projet mis à jour');
      const sRes = await projectsAPI.getBudgetStats(id);
      setStats(sRes.data);
    } catch (err) {
      const errors = err.response?.data;
      if (errors) Object.values(errors).flat().forEach(m => toast.error(m));
      else toast.error('Erreur lors de la sauvegarde');
    } finally {
      setSaving(false);
    }
  };

  const TYPE_ICONS = { batiment: '🏢', route: '🛣️', hydraulique: '💧', electricite: '⚡', autre: '🔧', aep: '💧', assainissement: '🚰', pont: '🌉' };

  if (loading) return (
    <AppLayout>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '60vh' }}>
        <div style={{ width: 40, height: 40, border: '3px solid var(--gold)', borderTopColor: 'transparent', borderRadius: '50%', animation: 'spin 1s linear infinite' }} />
      </div>
    </AppLayout>
  );

  if (!project) return null;

  const TABS = [
    { id: 'overview',   label: '📋 Vue d\'ensemble' },
    { id: 'budget',     label: '💰 Budget' },
    { id: 'contracts',  label: `📄 Contrats (${project.contracts?.length ?? 0})` },
    { id: 'journal',    label: '📓 Journal' },
  ];

  return (
    <AppLayout>
      <div style={{ padding: '40px 36px' }}>
        <div className="animate-fade-in" style={{ maxWidth: 1000 }}>

          <div style={{ marginBottom: 24 }}>
            <button onClick={() => navigate('/projects')} style={{ background: 'none', color: 'var(--gray-3)', fontSize: 14, cursor: 'pointer', marginBottom: 16, display: 'flex', alignItems: 'center', gap: 6 }}>
              ← Retour aux projets
            </button>
          </div>

          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 8 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 16, flex: 1 }}>
              <span style={{ fontSize: 36 }}>{TYPE_ICONS[project.project_type] || '🏗️'}</span>
              <div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 4 }}>
                  <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 26, fontWeight: 800 }}>{project.name}</h1>
                  <StatusBadge status={project.status} />
                </div>
                <div style={{ display: 'flex', gap: 16, color: 'var(--gray-3)', fontSize: 13 }}>
                  {project.reference && <span>#{project.reference}</span>}
                  {project.location && <span>📍 {project.location}</span>}
                  {project.client_name && <span>👤 {project.client_name}</span>}
                </div>
              </div>
            </div>
            <div style={{ display: 'flex', gap: 10 }}>
              {editing ? (
                <>
                  <button className="btn-secondary" onClick={() => { setEditing(false); setEditForm(project); }} style={{ padding: '10px 18px' }}>Annuler</button>
                  <button className="btn-primary" onClick={handleSave} disabled={saving} style={{ padding: '10px 18px' }}>
                    {saving ? '⏳...' : '✅ Sauvegarder'}
                  </button>
                </>
              ) : (
                <button className="btn-secondary" onClick={() => setEditing(true)} style={{ padding: '10px 18px', fontSize: 14 }}>
                  ✏️ Modifier
                </button>
              )}
            </div>
          </div>

          <div style={{ display: 'flex', gap: 0, borderBottom: '1px solid var(--dark-border)', marginBottom: 28, marginTop: 28 }}>
            {TABS.map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id)}
                style={{
                  padding: '12px 20px', fontSize: 14, fontWeight: 600, cursor: 'pointer',
                  background: 'none', border: 'none', outline: 'none',
                  color: activeTab === tab.id ? 'var(--gold)' : 'var(--gray-3)',
                  borderBottom: `2px solid ${activeTab === tab.id ? 'var(--gold)' : 'transparent'}`,
                  marginBottom: -1, transition: 'all 0.15s',
                }}>
                {tab.label}
              </button>
            ))}
          </div>

          {activeTab === 'overview' && (
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
              <div className="card">
                <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 15, fontWeight: 700, marginBottom: 16, color: 'var(--gold)' }}>📋 Informations générales</h3>
                {editing ? (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                    {[
                      { name: 'name', label: 'Nom', type: 'text' },
                      { name: 'reference', label: 'Référence', type: 'text' },
                      { name: 'client_name', label: 'Maître d\'ouvrage', type: 'text' },
                      { name: 'location', label: 'Localisation', type: 'text' },
                    ].map(f => (
                      <div key={f.name} className="input-group">
                        <label className="input-label">{f.label}</label>
                        <input className="input-field" type={f.type} value={editForm[f.name] || ''} onChange={e => setEditForm(p => ({ ...p, [f.name]: e.target.value }))} />
                      </div>
                    ))}
                    <div className="input-group">
                      <label className="input-label">Statut</label>
                      <select className="input-field" value={editForm.status || ''} onChange={e => setEditForm(p => ({ ...p, status: e.target.value }))}>
                        <option value="planifie">Planifié</option>
                        <option value="en_cours">En cours</option>
                        <option value="suspendu">Suspendu</option>
                        <option value="termine">Terminé</option>
                      </select>
                    </div>
                    <div className="input-group">
                      <label className="input-label">Description</label>
                      <textarea className="input-field" value={editForm.description || ''} onChange={e => setEditForm(p => ({ ...p, description: e.target.value }))} style={{ minHeight: 80, resize: 'vertical' }} />
                    </div>
                  </div>
                ) : (
                  <div>
                    <InfoRow label="Type" value={project.project_type_display} />
                    <InfoRow label="Référence" value={project.reference} />
                    <InfoRow label="Maître d'ouvrage" value={project.client_name} />
                    <InfoRow label="Localisation" value={project.location} />
                    {project.description && (
                      <div style={{ marginTop: 12, padding: 12, background: 'var(--dark-3)', borderRadius: 8 }}>
                        <div style={{ fontSize: 11, color: 'var(--gray-4)', textTransform: 'uppercase', marginBottom: 6 }}>Description</div>
                        <p style={{ fontSize: 13, color: 'var(--gray-2)', lineHeight: 1.6 }}>{project.description}</p>
                      </div>
                    )}
                  </div>
                )}
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div className="card">
                  <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 15, fontWeight: 700, marginBottom: 16, color: 'var(--gold)' }}>📅 Planning</h3>
                  {editing ? (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                      <div className="input-group">
                        <label className="input-label">Date de début</label>
                        <input className="input-field" type="date" value={editForm.start_date || ''} onChange={e => setEditForm(p => ({ ...p, start_date: e.target.value }))} />
                      </div>
                      <div className="input-group">
                        <label className="input-label">Date de fin prévue</label>
                        <input className="input-field" type="date" value={editForm.end_date || ''} onChange={e => setEditForm(p => ({ ...p, end_date: e.target.value }))} />
                      </div>
                    </div>
                  ) : (
                    <div>
                      <InfoRow label="Début" value={project.start_date ? new Date(project.start_date).toLocaleDateString('fr-FR', { day: '2-digit', month: 'long', year: 'numeric' }) : null} />
                      <InfoRow label="Fin prévue" value={project.end_date ? new Date(project.end_date).toLocaleDateString('fr-FR', { day: '2-digit', month: 'long', year: 'numeric' }) : null} />
                    </div>
                  )}
                </div>
                <div className="card">
                  <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 15, fontWeight: 700, marginBottom: 16, color: 'var(--gold)' }}>💰 Budget rapide</h3>
                  {editing ? (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                      <div className="input-group">
                        <label className="input-label">Budget prévisionnel (DA)</label>
                        <input className="input-field" type="number" value={editForm.budget || ''} onChange={e => setEditForm(p => ({ ...p, budget: e.target.value }))} />
                      </div>
                      <div className="input-group">
                        <label className="input-label">Dépenses réelles (DA)</label>
                        <input className="input-field" type="number" value={editForm.actual_expenses || 0} onChange={e => setEditForm(p => ({ ...p, actual_expenses: e.target.value }))} />
                      </div>
                    </div>
                  ) : (
                    <div>
                      <InfoRow label="Budget" value={project.budget ? `${(parseFloat(project.budget) / 1_000_000).toFixed(2)} M DA` : null} />
                      <InfoRow label="Dépensé" value={`${(parseFloat(project.actual_expenses || 0) / 1_000_000).toFixed(2)} M DA`} />
                      {project.budget_consumed_pct !== null && (
                        <div style={{ marginTop: 12 }}>
                          <div style={{ height: 6, background: 'var(--dark-border)', borderRadius: 3, overflow: 'hidden' }}>
                            <div style={{ height: '100%', width: `${Math.min(100, project.budget_consumed_pct)}%`, background: project.budget_consumed_pct > 85 ? '#EF4444' : 'var(--gold)', borderRadius: 3 }} />
                          </div>
                          <div style={{ fontSize: 12, color: 'var(--gray-4)', marginTop: 4 }}>{project.budget_consumed_pct}% consommé</div>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'budget' && <BudgetStats stats={stats} project={project} />}
          {activeTab === 'contracts' && <ContractsList contracts={project.contracts} />}
          {activeTab === 'journal' && <DailyReportsList projectId={id} />}

        </div>
      </div>
    </AppLayout>
  );
}
